import{_ as t,c as e,o as i,a0 as o}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Modello di definizione e monitoraggio degli obiettivi","description":"","frontmatter":{},"headers":[],"relativePath":"it/goal-template.md","filePath":"it/goal-template.md"}');const r=t({name:"it/goal-template.md"},[["render",function(t,a,r,n,l,d){return i(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="modello-di-definizione-e-monitoraggio-degli-obiettivi" tabindex="-1">Modello di definizione e monitoraggio degli obiettivi <a class="header-anchor" href="#modello-di-definizione-e-monitoraggio-degli-obiettivi" aria-label="Permalink to &quot;Modello di definizione e monitoraggio degli obiettivi&quot;">​</a></h1><h2 id="come-utilizzare-questo-modello" tabindex="-1">Come utilizzare questo modello <a class="header-anchor" href="#come-utilizzare-questo-modello" aria-label="Permalink to &quot;Come utilizzare questo modello&quot;">​</a></h2><p>Questo modello ti aiuta a stabilire obiettivi significativi e a monitorare sistematicamente i tuoi progressi. Copia le sezioni seguenti nel formato che preferisci (Word, Google Docs, Excel, Google Sheets o un blocco note).</p><div class="tip custom-block"><p class="custom-block-title">La filosofia dell&#39;impostazione degli obiettivi</p><p><strong>Gli obiettivi senza monitoraggio sono solo desideri. Il monitoraggio senza riflessione è solo dati.</strong> Questo modello combina entrambi: definizione chiara degli obiettivi e riflessione strutturata per garantire un miglioramento continuo.</p></div><h2 id="modello-di-definizione-degli-obiettivi-annuali" tabindex="-1">Modello di definizione degli obiettivi annuali <a class="header-anchor" href="#modello-di-definizione-degli-obiettivi-annuali" aria-label="Permalink to &quot;Modello di definizione degli obiettivi annuali&quot;">​</a></h2><h3 id="copia-questa-sezione-nel-tuo-documento" tabindex="-1">Copia questa sezione nel tuo documento <a class="header-anchor" href="#copia-questa-sezione-nel-tuo-documento" aria-label="Permalink to &quot;Copia questa sezione nel tuo documento&quot;">​</a></h3><hr><p><strong>Year:</strong> ________</p><p><strong>My Pétanque Vision for This Year:</strong></p><p>(In one sentence, what do I want to achieve this year?)</p><hr><h3 id="_1-obiettivi-della-competizione" tabindex="-1">1. Obiettivi della competizione <a class="header-anchor" href="#_1-obiettivi-della-competizione" aria-label="Permalink to &quot;1. Obiettivi della competizione&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tipo di obiettivo</th><th>Obiettivo specifico</th><th>Perché è importante</th><th>Misura del successo</th></tr></thead><tbody><tr><td><strong>Risultati del torneo</strong></td><td>Esempio: Primi 8 nel campionato regionale</td><td>Per dimostrare di poter competere a livello regionale</td><td>Piazzamento tra i primi 8</td></tr><tr><td><strong>Classifica</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Coerenza</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Prestazioni di squadra</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_2-obiettivi-tecnici" tabindex="-1">2. Obiettivi tecnici <a class="header-anchor" href="#_2-obiettivi-tecnici" aria-label="Permalink to &quot;2. Obiettivi tecnici&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area di competenza</th><th>Livello attuale (1-10)</th><th>Livello target</th><th>Focus specifico</th></tr></thead><tbody><tr><td><strong>Precisione di puntamento</strong></td><td></td><td></td><td>Esempio: 70% entro 10 cm a 7 m</td></tr><tr><td><strong>Coerenza di tiro</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Adattamento al terreno</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Selezione scatti</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_3-obiettivi-del-gioco-mentale" tabindex="-1">3. Obiettivi del gioco mentale <a class="header-anchor" href="#_3-obiettivi-del-gioco-mentale" aria-label="Permalink to &quot;3. Obiettivi del gioco mentale&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area</th><th>Stato attuale</th><th>Stato obiettivo</th><th>Metodo di pratica</th></tr></thead><tbody><tr><td><strong>Gestione della pressione</strong></td><td></td><td></td><td>Esempio: utilizzare il reset a 3 respiri prima di ogni tiro</td></tr><tr><td><strong>Critico interiore</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Focus/Concentrazione</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Fiducia</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="_4-obiettivi-fisici" tabindex="-1">4. Obiettivi fisici <a class="header-anchor" href="#_4-obiettivi-fisici" aria-label="Permalink to &quot;4. Obiettivi fisici&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area</th><th>Attuale</th><th>Obiettivo</th><th>Piano d&#39;azione</th></tr></thead><tbody><tr><td><strong>Livello di forma fisica</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Flessibilità</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Resistenza</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Prevenzione degli infortuni</strong></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="quarterly-review-template" tabindex="-1">Quarterly Review Template <a class="header-anchor" href="#quarterly-review-template" aria-label="Permalink to &quot;Quarterly Review Template&quot;">​</a></h2><h3 id="copy-this-section-every-3-months" tabindex="-1">Copy This Section Every 3 Months <a class="header-anchor" href="#copy-this-section-every-3-months" aria-label="Permalink to &quot;Copy This Section Every 3 Months&quot;">​</a></h3><hr><p><strong>Trimestre:</strong> Q1 / Q2 / Q3 / Q4 <strong>Data di revisione:</strong> ________</p><h3 id="cosa-e-andato-bene" tabindex="-1">Cosa è andato bene? <a class="header-anchor" href="#cosa-e-andato-bene" aria-label="Permalink to &quot;Cosa è andato bene?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="cosa-non-e-andato-come-previsto" tabindex="-1">Cosa non è andato come previsto? <a class="header-anchor" href="#cosa-non-e-andato-come-previsto" aria-label="Permalink to &quot;Cosa non è andato come previsto?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="apprendimenti-chiave" tabindex="-1">Apprendimenti chiave <a class="header-anchor" href="#apprendimenti-chiave" aria-label="Permalink to &quot;Apprendimenti chiave&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="adeguamenti-per-il-prossimo-trimestre" tabindex="-1">Adeguamenti per il prossimo trimestre <a class="header-anchor" href="#adeguamenti-per-il-prossimo-trimestre" aria-label="Permalink to &quot;Adeguamenti per il prossimo trimestre&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area obiettivo</th><th>Obiettivo originale</th><th>Adeguamento necessario</th><th>Nuovo obiettivo</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="monthly-goal-template" tabindex="-1">Monthly Goal Template <a class="header-anchor" href="#monthly-goal-template" aria-label="Permalink to &quot;Monthly Goal Template&quot;">​</a></h2><h3 id="copy-this-section-each-month" tabindex="-1">Copy This Section Each Month <a class="header-anchor" href="#copy-this-section-each-month" aria-label="Permalink to &quot;Copy This Section Each Month&quot;">​</a></h3><hr><p><strong>Mese:</strong> ________ <strong>Anno:</strong> ________</p><h3 id="focus-di-questo-mese" tabindex="-1">Focus di questo mese <a class="header-anchor" href="#focus-di-questo-mese" aria-label="Permalink to &quot;Focus di questo mese&quot;">​</a></h3><p><strong>Obiettivo primario:</strong></p><p><strong>Perché questo mese:</strong></p><h3 id="ripartizione-settimanale" tabindex="-1">Ripartizione settimanale <a class="header-anchor" href="#ripartizione-settimanale" aria-label="Permalink to &quot;Ripartizione settimanale&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Settimana</th><th>Obiettivo specifico</th><th>Focus di allenamento</th><th>Competizione/Test</th></tr></thead><tbody><tr><td><strong>Settimana 1</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Settimana 2</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Settimana 3</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Settimana 4</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="metriche-mensili-da-monitorare" tabindex="-1">Metriche mensili da monitorare <a class="header-anchor" href="#metriche-mensili-da-monitorare" aria-label="Permalink to &quot;Metriche mensili da monitorare&quot;">​</a></h3><ul><li>[ ] Sessioni di formazione completate: _____ / _____</li><li>[ ] Concorsi a cui si è partecipato: _____ / _____</li><li>[ ] Pratica di allenamento mentale: _____ giorni</li><li>[ ] Preparazione fisica: _____ sessioni</li><li>[ ] Riflessione/diario: _____ voci</li></ul><hr><h2 id="weekly-planning-template" tabindex="-1">Weekly Planning Template <a class="header-anchor" href="#weekly-planning-template" aria-label="Permalink to &quot;Weekly Planning Template&quot;">​</a></h2><h3 id="copy-this-section-each-week" tabindex="-1">Copy This Section Each Week <a class="header-anchor" href="#copy-this-section-each-week" aria-label="Permalink to &quot;Copy This Section Each Week&quot;">​</a></h3><hr><p><strong>Settimana del:</strong> ________</p><h3 id="intenzione-di-questa-settimana" tabindex="-1">Intenzione di questa settimana <a class="header-anchor" href="#intenzione-di-questa-settimana" aria-label="Permalink to &quot;Intenzione di questa settimana&quot;">​</a></h3><p>(Qual è il mio obiettivo principale questa settimana?)</p><h3 id="programma-di-allenamento" tabindex="-1">Programma di allenamento <a class="header-anchor" href="#programma-di-allenamento" aria-label="Permalink to &quot;Programma di allenamento&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Giorno</th><th>Attività</th><th>Durata</th><th>Area di interesse</th><th>Note</th></tr></thead><tbody><tr><td><strong>Lunedì</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Martedì</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Mercoledì</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Giovedì</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Venerdì</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Sabato</strong></td><td></td><td></td><td></td><td></td></tr><tr><td><strong>Domenica</strong></td><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="obiettivi-settimanali" tabindex="-1">Obiettivi settimanali <a class="header-anchor" href="#obiettivi-settimanali" aria-label="Permalink to &quot;Obiettivi settimanali&quot;">​</a></h3><ul><li>[ ] Pratica tecnica: _____ ore</li><li>[ ] Competizione/partita: _____ ore</li><li>[ ] Allenamento mentale: _____ minuti</li><li>[ ] Allenamento fisico: _____ sessioni</li><li>[ ] Analisi video: _____ sessioni</li></ul><hr><h2 id="progress-tracking-sheet" tabindex="-1">Progress Tracking Sheet <a class="header-anchor" href="#progress-tracking-sheet" aria-label="Permalink to &quot;Progress Tracking Sheet&quot;">​</a></h2><h3 id="copy-this-to-excel-google-sheets" tabindex="-1">Copy This to Excel/Google Sheets <a class="header-anchor" href="#copy-this-to-excel-google-sheets" aria-label="Permalink to &quot;Copy This to Excel/Google Sheets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Goal Area</th><th>Target</th><th>Actual</th><th>Notes</th><th>Feeling (1-10)</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Instructions for Spreadsheet:</strong></p><ol><li>Create columns: Date, Goal Area, Target, Actual, Notes, Feeling</li><li>Add new row after each training session or competition</li><li>Use conditional formatting: Green if Actual ≥ Target, Yellow if close, Red if far off</li><li>Create charts to visualize progress over time</li></ol><hr><h2 id="tracker-delle-prestazioni-della-concorrenza" tabindex="-1">Tracker delle prestazioni della concorrenza <a class="header-anchor" href="#tracker-delle-prestazioni-della-concorrenza" aria-label="Permalink to &quot;Tracker delle prestazioni della concorrenza&quot;">​</a></h2><h3 id="copia-questo-per-monitorare-i-risultati-del-torneo" tabindex="-1">Copia questo per monitorare i risultati del torneo <a class="header-anchor" href="#copia-questo-per-monitorare-i-risultati-del-torneo" aria-label="Permalink to &quot;Copia questo per monitorare i risultati del torneo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Data</th><th>Torneo</th><th>Turno raggiunto</th><th>Posizionamento</th><th>Punti di forza chiave</th><th>Aree da migliorare</th><th>Stato mentale (1-10)</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="goal-achievement-celebration" tabindex="-1">Goal Achievement Celebration <a class="header-anchor" href="#goal-achievement-celebration" aria-label="Permalink to &quot;Goal Achievement Celebration&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Celebrate Progress!</p><p><strong>Every goal achieved deserves recognition.</strong> When you hit a target:</p><ol><li>✅ Mark it complete</li><li>🎉 Acknowledge the effort it took</li><li>📝 Write what you learned</li><li>🎯 Set the next challenge</li></ol></div><h3 id="achievement-log" tabindex="-1">Achievement Log <a class="header-anchor" href="#achievement-log" aria-label="Permalink to &quot;Achievement Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Goal Achieved</th><th>What It Took</th><th>Key Learning</th><th>Next Challenge</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="suggerimenti-per-una-definizione-efficace-degli-obiettivi" tabindex="-1">Suggerimenti per una definizione efficace degli obiettivi <a class="header-anchor" href="#suggerimenti-per-una-definizione-efficace-degli-obiettivi" aria-label="Permalink to &quot;Suggerimenti per una definizione efficace degli obiettivi&quot;">​</a></h2><h3 id="_1-inizia-in-piccolo-crea-slancio" tabindex="-1">1. Inizia in piccolo, crea slancio <a class="header-anchor" href="#_1-inizia-in-piccolo-crea-slancio" aria-label="Permalink to &quot;1. Inizia in piccolo, crea slancio&quot;">​</a></h3><p>Non fissare 20 obiettivi contemporaneamente. Inizia con:</p><ul><li><strong>1 gol in gara</strong></li><li><strong>1 obiettivo tecnico</strong></li><li><strong>1 obiettivo di gioco mentale</strong></li></ul><p>Impara a monitorare questi aspetti prima di aggiungerne altri.</p><h3 id="_2-rivedi-regolarmente" tabindex="-1">2. Rivedi regolarmente <a class="header-anchor" href="#_2-rivedi-regolarmente" aria-label="Permalink to &quot;2. Rivedi regolarmente&quot;">​</a></h3><ul><li><strong>Giornaliero:</strong> Controlla l&#39;intenzione di oggi</li><li><strong>Settimanale:</strong> Rivedi i progressi della settimana, pianifica la settimana successiva</li><li><strong>Mensile:</strong> Valutare gli obiettivi mensili, apportare modifiche se necessario</li><li><strong>Trimestrale:</strong> Riflessioni approfondite, importanti aggiustamenti</li><li><strong>Annualmente:</strong> Festeggia l&#39;anno, definisci una nuova visione</li></ul><h3 id="_3-sii-onesto-non-duro" tabindex="-1">3. Sii onesto, non duro <a class="header-anchor" href="#_3-sii-onesto-non-duro" aria-label="Permalink to &quot;3. Sii onesto, non duro&quot;">​</a></h3><p>Quando manchi un bersaglio:</p><ul><li>❌ <strong>Non fare:</strong> &quot;Sono terribile, non migliorerò mai&quot;</li><li>✅ <strong>Fai:</strong> &quot;Cosa mi ha intralciato? Cosa posso sistemare?&quot;</li></ul><h3 id="_4-collega-gli-obiettivi-al-tuo-perche" tabindex="-1">4. Collega gli obiettivi al tuo perché <a class="header-anchor" href="#_4-collega-gli-obiettivi-al-tuo-perche" aria-label="Permalink to &quot;4. Collega gli obiettivi al tuo perché&quot;">​</a></h3><p>Ogni obiettivo dovrebbe essere collegato alla tua motivazione più profonda:</p><ul><li>Perché giochi a bocce?</li><li>Cosa significa per te miglioramento?</li><li>Come ti sentirai dopo aver raggiunto questo obiettivo?</li></ul><h3 id="_5-rendilo-visibile" tabindex="-1">5. Rendilo visibile <a class="header-anchor" href="#_5-rendilo-visibile" aria-label="Permalink to &quot;5. Rendilo visibile&quot;">​</a></h3><ul><li>Stampa i tuoi obiettivi annuali e affiggili dove li vedi ogni giorno</li><li>Imposta promemoria telefonici per le revisioni settimanali</li><li>Condividi gli obiettivi con il tuo compagno di allenamento per responsabilizzarti</li></ul><hr><h2 id="digital-vs-paper-tracking" tabindex="-1">Digital vs. Paper Tracking <a class="header-anchor" href="#digital-vs-paper-tracking" aria-label="Permalink to &quot;Digital vs. Paper Tracking&quot;">​</a></h2><h3 id="digital-google-sheets-excel" tabindex="-1">Digital (Google Sheets/Excel) <a class="header-anchor" href="#digital-google-sheets-excel" aria-label="Permalink to &quot;Digital (Google Sheets/Excel)&quot;">​</a></h3><p><strong>Pros:</strong></p><ul><li>Easy to update anywhere</li><li>Automatic calculations and charts</li><li>Can share with coach/training partner</li><li>Search and filter data</li></ul><p><strong>Cons:</strong></p><ul><li>Requires device</li><li>Can feel impersonal</li><li>Easy to ignore notifications</li></ul><h3 id="paper-notebook-printed-templates" tabindex="-1">Paper (Notebook/Printed Templates) <a class="header-anchor" href="#paper-notebook-printed-templates" aria-label="Permalink to &quot;Paper (Notebook/Printed Templates)&quot;">​</a></h3><p><strong>Pros:</strong></p><ul><li>Tactile, personal connection</li><li>No distractions</li><li>Easy to review during training</li><li>Satisfying to check boxes</li></ul><p><strong>Cons:</strong></p><ul><li>Can&#39;t easily create charts</li><li>Risk of losing notebook</li><li>Harder to share</li></ul><p><strong>Recommendation:</strong> Use both! Digital for data tracking, paper for daily intentions and reflections.</p><hr><h2 id="risorse-correlate" tabindex="-1">Risorse correlate <a class="header-anchor" href="#risorse-correlate" aria-label="Permalink to &quot;Risorse correlate&quot;">​</a></h2><ul><li><a href="/it/workshop">Workshop</a> - Sessioni di gruppo sulla definizione degli obiettivi e sul gioco mentale</li><li><a href="/it/training-session">Sessione di formazione</a> - Esercitati con i partner responsabili</li><li><a href="/it/education/mental-strength">Forza mentale</a> - Sviluppa la mentalità per raggiungere gli obiettivi</li><li><a href="/it/diary-template">Modello di diario di allenamento</a> - Monitoraggio della pratica quotidiana</li></ul><hr><h2 id="quick-start-guide" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start-guide" aria-label="Permalink to &quot;Quick Start Guide&quot;">​</a></h2><p><strong>New to goal setting? Start here:</strong></p><ol><li><strong>Week 1:</strong> Set ONE monthly goal using SMART framework</li><li><strong>Week 2:</strong> Track daily progress in simple table</li><li><strong>Week 3:</strong> Do first weekly review</li><li><strong>Week 4:</strong> Adjust goal if needed, celebrate progress</li></ol><p><strong>After one month:</strong> Add quarterly and annual goals.</p><hr><p>::: Attenzione Errori comuni nella definizione degli obiettivi</p><ol><li><strong>Troppi obiettivi</strong> - La concentrazione è diluita</li><li><strong>Troppo vago</strong> - &quot;Migliorare&quot; non è misurabile</li><li><strong>Nessun monitoraggio</strong> - Non è possibile visualizzare i progressi</li><li><strong>Nessuna revisione</strong> - Perdere opportunità di adattamento</li><li><strong>Tutti i risultati, nessun processo</strong> - Concentrati su ciò che puoi controllare :::</li></ol><hr><h2 id="download-templates" tabindex="-1">Download Templates <a class="header-anchor" href="#download-templates" aria-label="Permalink to &quot;Download Templates&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Copy-Paste Ready</p><p>All templates on this page are designed to be copied directly into:</p><ul><li>Microsoft Word</li><li>Google Docs</li><li>Microsoft Excel</li><li>Google Sheets</li><li>Notion</li><li>Any note-taking app</li></ul><p>Simply select the template section you want, copy (Ctrl+C / Cmd+C), and paste into your preferred tool.</p></div><p><strong>Start with these three:</strong></p><ol><li>Annual Goal Setting Template</li><li>Weekly Planning Template</li><li>Progress Tracking Sheet</li></ol><hr><p>Utilizza questo schema per rendere i tuoi obiettivi specifici e raggiungibili:</p><h3 id="modello-di-obiettivo-smart" tabindex="-1">Modello di obiettivo SMART <a class="header-anchor" href="#modello-di-obiettivo-smart" aria-label="Permalink to &quot;Modello di obiettivo SMART&quot;">​</a></h3><p><strong>S - Specifico:</strong> (Cosa voglio ottenere esattamente?)</p><p><strong>M - Misurabile:</strong> (Come farò a sapere di averlo raggiunto?)</p><p><strong>A - Raggiungibile:</strong> (È realistico, dato il mio livello attuale e le mie risorse?)</p><p><strong>R - Rilevante:</strong> (Perché questo è importante per la mia visione generale?)</p><p><strong>T - Limitato nel tempo:</strong> (Entro quando riuscirò a raggiungere questo obiettivo?)</p><h3 id="esempi-di-obiettivi-smart" tabindex="-1">Esempi di obiettivi SMART <a class="header-anchor" href="#esempi-di-obiettivi-smart" aria-label="Permalink to &quot;Esempi di obiettivi SMART&quot;">​</a></h3><details class="details custom-block"><summary>Esempio 1: Obiettivo tecnico</summary><p><strong>S - Specifico:</strong> Migliora la precisione di puntamento su terreni duri <strong>M - Misurabile:</strong> Atterrare entro 20 cm dal cochonnet 7 tentativi su 10 <strong>A - Raggiungibile:</strong> Attualmente a 4/10, quindi 7/10 è impegnativo ma realistico <strong>R - Rilevante:</strong> Il terreno duro è comune nei tornei regionali <strong>T - Limitato nel tempo:</strong> Da raggiungere entro la fine del secondo trimestre (30 giugno)</p></details><details class="details custom-block"><summary>Esempio 2: Obiettivo della competizione</summary><p><strong>S - Specifico:</strong> Raggiungere le semifinali nel campionato per club <strong>M - Misurabile:</strong> Arrivare tra i primi 4 in un torneo da 32 giocatori <strong>A - Raggiungibile:</strong> Attualmente classificato 8-12 nel club, il miglioramento è realistico <strong>R - Rilevante:</strong> Crea fiducia e dimostra i progressi <strong>T - Limitato nel tempo:</strong> Il campionato è il 15 settembre</p></details><details class="details custom-block"><summary>Esempio 3: Obiettivo del gioco mentale</summary><p><strong>S - Specifico:</strong> Gestire il critico interiore durante la competizione <strong>M - Misurabile:</strong> Usa Inner Coach per riformulare dopo ogni errore <strong>A - Raggiungibile:</strong> Aver praticato la tecnica durante l&#39;allenamento <strong>R - Rilevante:</strong> Il dialogo interiore negativo è il mio più grande ostacolo <strong>T - Limitato nel tempo:</strong> Utilizzo costante nei prossimi 3 tornei</p></details><hr>',128)])])}]]);export{a as __pageData,r as default};
